
var font = '';


var boldFont = '';
var callAddFont = function () {
this.addFileToVFS('Roboto-VariableFont_wdth,wght-normal.ttf', font);
this.addFont('Roboto-VariableFont_wdth,wght-normal.ttf', 'Roboto-VariableFont_wdth,wght', 'normal');

this.addFileToVFS('Roboto-Bold-normal.ttf', boldFont);
this.addFont('Roboto-Bold-normal.ttf', 'Roboto-Bold', 'bold');
};
